        out.push({ key: lin2hex(M.keys[id]), n: s.n, nearDL: s.near[0] / Math.max(1, s.near[1]), farDL: s.far[0] / Math.max(1, s.far[1]), farCoreDL: s.farIn[0] / Math.max(1, s.farIn[1]), nNear: s.near[1], nFar: s.far[1], nFarCore: s.farIn[1],
