    },
    // vệt DOF trên đầu: dải 1–6 px trên mép trên khối người (mặt nạ không co); trả ảnh DOF bật (dilate | v4) và tắt để tính ΔL* theo cột ở Python
    async streak(frame) {
      const dof = state.passes.dof; if (!dof) return null;
