    state, opts: O, meas,
    // gọi SAU boot cảnh gốc: render khô một khung (vẽ gốc) để bắt (renderer, scene, cam) thật
    async prepare(frame) {
      if (off) return;
      frame(0);
      if (!state.cap) throw new Error('cine: cảnh không gọi renderer.render');
      await prep(...state.cap);
    },
  };
}

