    20	    : spine.shots.flatMap((s) => Array.from({ length: per }, (_, k) => +(s.t0 + (s.t1 - s.t0) * (k + 1) / (per + 1)).toFixed(3)));
    21	  const stills = arg('--stills') ? path.resolve(arg('--stills')) : null; if (stills) fs.mkdirSync(stills, { recursive: true });
    22	  const browser = await chromium.launch({ args: ['--font-render-hinting=none', '--disable-lcd-text', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
