    42	      const fr = (x) => APP.frame(x); fr(t);
    43	      const shot = CINE.state.cfg || {}, out = { t, shot: shot.shot || null, data: await CINE.meas.data(b) };
    44	      if (rim && CINE.state.people.length) out.rim = await CINE.meas.rim(b, fr);
    45	      if (streak && shot.shot === 'close' && CINE.state.passes.dof) out.streak = await CINE.meas.streak(fr);
    46	      fr(t); out.png = CINE.state.renderer.domElement.toDataURL('image/png');
