    54	  }
    55	  const roof = await cine.evaluate(() => CINE.state.stats);
    56	  await browser.close();
    57	  fs.writeFileSync(path.resolve(outRel), JSON.stringify({ seg: segDir, res, cine: spine.cine, samples, roof }, null, 1));
    58	})().catch((e) => { console.error(e); process.exit(1); });
